import{d as q,C as L,o as P,c,a3 as r,E as i,j as s,a as t}from"./chunks/framework.Q4yG9rk_.js";const V=JSON.parse('{"title":"孟子·万章上","description":"《孟子》第 9 篇「万章上」——大孝终身慕父母、舜之不告而娶、象日以杀舜为事、天与之、天与贤则与贤、伊尹以割烹要汤。","frontmatter":{"title":"孟子·万章上","description":"《孟子》第 9 篇「万章上」——大孝终身慕父母、舜之不告而娶、象日以杀舜为事、天与之、天与贤则与贤、伊尹以割烹要汤。","category":"guide","aliases":["万章上","万章章句上","mengzi 万章上"],"source":["《孟子》"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/mengzi/chapter-09.md","filePath":"lizhimingde/sishu-wujing/mengzi/chapter-09.md","lastUpdated":1790316338000}'),D={name:"lizhimingde/sishu-wujing/mengzi/chapter-09.md"},C=q({...D,setup(_){const e=[{id:"jie1_s1",label:"舜往于田，号泣于旻天",showLabel:!0,sentences:[["万章问曰：“舜往于田，号泣于",{text:"旻天",glossary:"minTian"},"。何为其号泣也？”孟子曰：“",{text:"怨慕",glossary:"yuanmu"},"也。”万章曰：“父母爱之，喜而不忘；父母恶之，劳而不怨。然则舜怨乎？”"]],note:"万章问：「舜到田里去耕种，对着上天哭号。他为什么哭号呢？」孟子说：「因为怨慕（怨自己不得父母欢心，又思慕父母）。」万章说：「父母喜爱他，就高兴而不忘怀；父母厌恶他，就勤劳而不怨恨。那么舜是怨恨父母吗？」"},{id:"jie1_s2",label:"公明高以孝子之心为不若是恝",showLabel:!0,sentences:[["曰：“长息问于公明高曰：‘舜往于田，则吾既得闻命矣；号泣于旻天、于父母，则吾不知也。’公明高曰：‘是非尔所知也。’夫公明高以孝子之心为不若是",{text:"恝",glossary:"jia-2"},"。‘我竭力耕田，共为子职而已矣；父母之不我爱，于我何哉？’"]],note:"孟子说：「长息问公明高：『舜到田里去耕种，我已经听您讲过了；可他对着上天、对着父母哭号，我就不明白了。』公明高说：『这不是你所能懂的。』公明高认为，孝子的心不会这样无动于衷。（舜不是这样想：）『我尽力耕田，尽我做儿子的本分就是了；父母不喜爱我，跟我有什么关系呢？』"},{id:"jie1_s3",label:"大孝终身慕父母",showLabel:!0,sentences:[["帝使其子九男二女，百官牛羊仓廩备，以事舜于畎亩之中。天下之士多就之者，帝将",{text:"胥",glossary:"xu-2"},"天下而迁之焉。为不顺于父母，如穷人无所归。天下之士悦之，人之所欲也，而不足以解忧。好色，人之所欲；妻帝之二女，而不足以解忧。富，人之所欲；富有天下，而不足以解忧。贵，人之所欲；贵为天子，而不足以解忧。人悦之、好色、富贵无足以解忧者，惟顺于父母，可以解忧。人少则慕父母，知好色则慕少艾，有妻子则慕妻子，仕则慕君，不得于君则热中。大孝终身慕父母，五十而慕者，予于大舜见之矣。”"]],note:"孟子接着说：「尧派自己的九个儿子、两个女儿，加上百官、牛羊、仓廩，齐备地到田间去侍奉舜。天下的士人有许多去归附他，尧还要把整个天下都让给他。可舜因为不得父母的欢心，就像穷困的人无处可归。天下的士人喜欢他，是人人所想要的，却不足以解他的忧愁；美貌，人人所想要，娶了尧的两个女儿，也不足以解忧；财富，人人所想要，富有天下，也不足以解忧；尊贵，人人所想要，贵为天子，也不足以解忧。别人的喜欢、美貌、富贵都不能解忧，只有顺了父母的心，才能解忧。人小的时候思慕父母，懂得爱慕异性就思慕年轻貌美的人，有了妻儿就思慕妻儿，做了官就思慕君主，得不到君主的欢心就心里焦躁。而大孝的人终身思慕父母——到了五十岁还思慕父母的，我在大舜身上看到了。」"}],l=[{id:"minTian",term:"旻天",pinyin:"mín tiān",meaning:"泛指天（旻：秋天，一说为怜恤之意）。「号泣于旻天」谓对着上天哭号。"},{id:"yuanmu",term:"怨慕",pinyin:"yuàn mù",meaning:"怨自己不得父母欢心，又思慕父母（怨：怨己；慕：思慕）。这是理解舜之号泣的关键。"},{id:"jia-2",term:"恝",pinyin:"jiá",meaning:"无忧、淡然不在意。「不若是恝」谓孝子的心不会这样漠然置之。"},{id:"xu-2",term:"胥",pinyin:"xū",meaning:"皆、尽。「胥天下而迁之」谓把整个天下都让给他。"}],a=[{id:"jie2_s1",label:"舜之不告而娶，何也",showLabel:!0,sentences:[["万章问曰：“《诗》云：‘娶妻如之何？必告父母。’信斯言也，宜莫如舜。舜之不告而娶，何也？”孟子曰：“告则不得娶。男女居室，人之大伦也。如告则废人之大伦以",{text:"懟",glossary:"dui-2"},"父母，是以不告也。”万章曰：“舜之不告而娶，则吾既得闻命矣。帝之妻舜而不告，何也？”曰：“帝亦知告焉则不得妻也。”"]],note:"万章问：「《诗》上说：『娶妻该怎样？一定要禀告父母。』照这话，最该遵行的莫过于舜。可舜不禀告就娶妻，为什么？」孟子说：「禀告了就娶不成。男女成家，是人的大伦；如果禀告就会废掉人伦、又让父母担怨，所以不禀告。」万章说：「舜不禀告就娶妻，我已经听明白了。那么尧把女儿嫁给舜也不禀告舜的父母，为什么？」孟子说：「尧也知道禀告了就嫁不成。」"},{id:"jie2_s2",label:"父母使舜完廩，捐阶",showLabel:!0,sentences:[["万章曰：“父母使舜完廩，捐阶，瞽瞍焚廩。使浚井，出，从而掩之。象曰：‘谟盖都君咸我绩。牛羊父母，仓廩父母，干戈朕，琴朕，",{text:"弤",glossary:"di-2"},"朕，二嫂使治朕栖。’象往入舜宫，舜在床琴。象曰：‘郁陶思君尔。’忸怩。舜曰：‘唯兹臣庶，汝其于予治。’不识舜不知象之将杀己与？”"]],note:"万章说：「舜的父母让他去修粮仓，却抽掉梯子，瞽瞍放火烧仓。又让他去淘井，（舜）出来了，他们就填土掩井。象说：『谋害舜都是我的功劳。牛羊归父母，仓廩归父母，干戈归我，琴归我，弓归我，两位嫂子让她们替我管家。』象走进舜的宫室，舜正坐在床上弹琴。象说：『我正闷闷地想念你哪。』脸上却羞惭不安。舜说：『这些臣民，你就替我管理吧。』不知道舜是不是不知道象要杀自己？」"},{id:"jie2_s3",label:"君子可欺以其方，难罔以非其道",showLabel:!0,sentences:[["曰：“奚而不知也？象忧亦忧，象喜亦喜。”曰：“然则舜伪喜者与？”曰：“否。昔者有馈生鱼于郑子产，子产使校人畜之池。校人烹之，反命曰：‘始舍之",{text:"圉圉",glossary:"yuyu"},"焉，少则",{text:"洋洋",glossary:"yangyang"},"焉，攸然而逝。’子产曰：‘得其所哉！得其所哉！’校人出，曰：‘孰谓子产智？予既烹而食之，曰：“得其所哉！得其所哉！”’故君子可欺以其方，难罔以非其道。彼以爱兄之道来，故诚信而喜之。奚伪焉？”"]],note:"孟子说：「怎么不知道呢？只是象忧愁他也忧愁，象欢喜他也欢喜。」万章说：「那么舜是假装欢喜吗？」孟子说：「不是。从前有人送活鱼给郑国的子产，子产让管池子的人养在池里；那人却把鱼煮了吃了，回来报告说：『刚放下去时它还蔫蔫的，一会儿就活络起来，忽然一甩尾巴不见了。』子产说：『找到好去处了！找到好去处了！』那人出来后说：『谁说子产聪明？我已经把鱼煮着吃了，他还说「找到好去处了」。』所以君子可以用合乎情理的话去欺骗，却难以用违背道理的手段去蒙蔽。象是用敬爱兄长的说辞来的，所以舜就真诚地相信并高兴了——哪里是假装呢？」"}],g=[{id:"dui-2",term:"懟",pinyin:"duì",meaning:"怨恨。「废人之大伦以懟父母」谓若禀告而娶不成，既废弃人伦，又使父母招怨。"},{id:"di-2",term:"弤",pinyin:"dǐ",meaning:"雕画过的弓（一说为漆过的弓）。象索取舜的财物，此为其一。"},{id:"yuyu",term:"圉圉",pinyin:"yǔ yǔ",meaning:"鱼刚被放开时疲弱不动的样子。"},{id:"yangyang",term:"洋洋",pinyin:"yáng yáng",meaning:"舒缓自得的样子。此谓鱼渐渐活动起来。"}],u=[{id:"jie3_s1",label:"象日以杀舜为事",showLabel:!0,sentences:[["万章问曰：“象日以杀舜为事，立为天子，则放之，何也？”孟子曰：“封之也。或曰放焉。”万章曰：“舜流",{text:"共工",glossary:"gonggong"},"于幽州，放",{text:"驩兜",glossary:"huandou"},"于崇山，杀三苗于三危，",{text:"殛鲧",glossary:"jigun"},"于羽山，四罪而天下咸服。诛不仁也。象至不仁，封之有庳。有庳之人奚罪焉？仁人固如是乎？在他人则诛之，在弟则封之。”"]],note:"万章问：「象天天把杀舜当作正事，舜做了天子，却只是放逐他，为什么？」孟子说：「是封他。也有人说是放逐。」万章说：「舜把共工流放到幽州，把驩兜放逐到崇山，把三苗杀死在三危，把鲧处死在羽山——处置了这四个罪人，天下都心服。这是惩罚不仁的人。象最不仁，却封在有庳。有庳的百姓有什么罪过呢？仁人难道该这样吗？对别人就惩罚，对弟弟就封赏。」"},{id:"jie3_s2",label:"仁人之于弟也，不藏怒焉，不宿怨焉",showLabel:!0,sentences:[["曰：“仁人之于弟也，不藏怒焉，不宿怨焉，亲爱之而已矣。亲之，欲其贵也；爱之，欲其富也。封之有庳，富贵之也。身为天子，弟为匹夫，可谓亲爱之乎？”「敢问『或曰放』者何谓也？”"]],note:"孟子说：「仁人对于弟弟，不藏怒气，不留怨恨，只是亲爱他罢了。亲他，就希望他尊贵；爱他，就希望他富有。封他到有庳，就是让他富贵。自己身为天子，弟弟却是平民，能叫亲爱他吗？」万章说：「请问『有人说是放逐』是什么意思？」"},{id:"jie3_s3",label:"象不得有为于其国",showLabel:!0,sentences:[["曰：“象不得有为于其国，天子使吏治其国，而纳其贡税焉，故谓之放。岂得暴彼民哉？虽然，欲常常而见之，故源源而来。‘不及贡，以政接于有庳’，此之谓也。”"]],note:"孟子说：「象不能在他的封国里有所作为，天子派官吏去治理他的封国，只收取贡税，所以叫做放逐。这样怎么会残害那里的百姓呢？虽然如此，舜想常常见到他，所以让他不断地来朝见。所谓『不等贡期，就以政事的名义接见有庳的君主』，说的就是这个。」"}],d=[{id:"gonggong",term:"共工",pinyin:"gòng gōng",meaning:"传说中尧舜时的罪臣。下文驩兜、三苗、鲧，合称「四罪」，俱被舜所处置。"},{id:"huandou",term:"驩兜",pinyin:"huān dōu",meaning:"传说中与共工同党的罪臣（驩：同「欢」）。"},{id:"jigun",term:"殛鲧",pinyin:"jí gǔn",meaning:"处死鲧（殛：诛杀、流放；鲧：禹的父亲，治水无功而被诛）。"}],h=[{id:"jie4_s1",label:"此非君子之言，齐东野人之语也",showLabel:!0,sentences:[["咸丘蒙问曰：“语云：‘盛德之士，君不得而臣，父不得而子。’舜南面而立，尧帅诸侯北面而朝之，瞽瞍亦北面而朝之。舜见瞽瞍，其容有",{text:"蹙",glossary:"cu-2"},"。孔子曰：‘于斯时也，天下殆哉，岌岌乎！’不识此语，诚然乎哉？”孟子曰：“否，此非君子之言，齐东野人之语也。尧老而舜摄也，《尧典》曰：‘二十有八载，放勋乃",{text:"徂落",glossary:"culuo"},"，百姓如丧考妣。三年，四海遏密八音。’孔子曰：‘天无二日，民无二王。’舜既为天子矣，又帅天下诸侯以为尧三年丧，是二天子矣。”"]],note:"咸丘蒙问：「古语说：『盛德之士，君主不能以他为臣，父亲不能以他为子。』舜做了天子面南而坐，尧带着诸侯面北朝见他，瞽瞍也面北朝见他。舜见到瞽瞍，脸上有不安的神色。孔子说：『那个时候，天下危险啊，岌岌可危！』不知道这话，是真的吗？」孟子说：「不对，这不是君子的话，是齐国东边乡下人的话。事实是尧年老而舜代摄政事。《尧典》上说：『过了二十八年，尧去世了，百姓像死了父母一样。三年之内，四海停止了音乐。』孔子说：『天上没有两个太阳，百姓没有两个君王。』舜如果已经是天子，又带着天下诸侯为尧守三年之丧，那就是两个天子了。」"},{id:"jie4_s2",label:"不以文害辞，不以辞害志",showLabel:!0,sentences:[["咸丘蒙曰：“舜之不臣尧，则吾既得闻命矣。《诗》云：‘普天之下，莫非王土；率土之滨，莫非王臣。’而舜既为天子矣，敢问瞽瞍之非臣，如何？”曰：“是诗也，非是之谓也，劳于王事而不得养父母也。曰：‘此莫非王事，我独贤劳也。’故说诗者，不以文害辞，不以辞害志；以意逆志，是为得之。如以辞而已矣。《云汉》之诗曰：‘周余黎民，靡有孑遗。’信斯言也，是周无遗民也。"]],note:"咸丘蒙说：「舜不以尧为臣，我已经听明白了。《诗》上说：『普天之下，没有不是王的土地；沿着土地直到海边，没有不是王的臣民。』可舜已经是天子了，请问瞽瞍却不算他的臣民，怎么解释？」孟子说：「这首诗不是这个意思，它说的是（臣子）为王事操劳而不能奉养父母。意思是：『这些莫非都是王事，却只有我一个人在辛苦。』所以解说《诗》的人，不要因文字而妨碍词句，不要因词句而妨碍本意；用自己的体会去推求作者的本意，这才算懂了。如果只就字面看，《云汉》那首诗说：『周朝剩下的百姓，没有一个留下来。』要是相信这话，那周朝就没有剩下的百姓了。」"},{id:"jie4_s3",label:"孝子之至，莫大乎尊亲",showLabel:!0,sentences:[["孝子之至，莫大乎尊亲；尊亲之至，莫大乎以天下养。为天子父，尊之至也；以天下养，养之至也。《诗》曰：‘永言孝思，孝思惟则’，此之谓也。《书》曰：‘",{text:"祗载",glossary:"zhizai"},"见瞽瞍，",{text:"夔夔斋栗",glossary:"kuikuizhaili"},"，瞽瞍亦允若’，是为父不得而子也？”"]],note:"孟子接着说：「孝子的极致，没有大过尊敬父母的；尊敬父母的极致，没有大过拿天下来奉养父母。做天子的父亲，是尊贵的极致；拿天下来奉养，是奉养的极致。《诗》上说：『永远想着孝，孝就是法则』，说的就是这个。《书》上说：『（舜）恭敬地来见瞽瞍，战战兢兢、恭谨畏惧，瞽瞍也就相信了他、顺了他』——这哪里是『父亲不能以他为子』呢？」"}],m=[{id:"cu-2",term:"蹙",pinyin:"cù",meaning:"皱眉、神色不安。"},{id:"culuo",term:"徂落",pinyin:"cú luò",meaning:"死亡（徂：往；落：陨）。「放勋乃徂落」谓尧去世（放勋是尧的号）。"},{id:"zhizai",term:"祗载",pinyin:"zhī zài",meaning:"恭敬地从事（祗：敬；载：事、行）。"},{id:"kuikuizhaili",term:"夔夔斋栗",pinyin:"kuí kuí zhāi lì",meaning:"恭谨畏惧的样子（夔夔：戒惧敬慎之貌；斋栗：敬谨恐惧）。"}],p=[{id:"jie5_s1",label:"天子不能以天下与人",showLabel:!0,sentences:[["万章曰：“尧以天下与舜，有诸？”孟子曰：“否，天子不能以天下与人。”“然则舜有天下也，孰与之？”曰：“天与之。”“天与之者，谆谆然命之乎？”曰：“否，天不言，以行与事示之而已矣。”曰：“以行与事示之者，如之何？”"]],note:"万章说：「尧把天下给了舜，有这回事吗？」孟子说：「没有，天子不能把天下给别人。」「那么舜拥有天下，是谁给他的？」孟子说：「是天给他的。」「天给他，是絮絮叨叨地告诫他吗？」孟子说：「不是，天不说话，只是用行为和事实显示出来罢了。」万章说：「用行为和事实显示，是怎样的呢？」"},{id:"jie5_s2",label:"昔者尧荐舜于天而天受之",showLabel:!0,sentences:[["曰：“天子能荐人于天，不能使天与之天下；诸侯能荐人于天子，不能使天子与之诸侯；大夫能荐人于诸侯，不能使诸侯与之大夫。昔者尧荐舜于天而天受之，暴之于民而民受之。故曰：天不言，以行与事示之而已矣。”曰：“敢问荐之于天而天受之，暴之于民而民受之，如何？”曰：“使之主祭而百神享之，是天受之。使之主事而事治，百姓安之，是民受之也。天与之，人与之，故曰：天子不能以天下与人。"]],note:"孟子说：「天子能够向天推荐人，却不能使天把天下给他；诸侯能够向天子推荐人，却不能使天子把诸侯之位给他；大夫能够向诸侯推荐人，却不能使诸侯把大夫之位给他。从前尧向天推荐舜，天接受了；又把他公开给百姓，百姓也接受了。所以说：天不说话，只是用行为和事实显示出来罢了。」万章说：「请问向天推荐而天接受、公开给百姓而百姓接受，是怎样的？」孟子说：「让他主持祭祀而百神享用，就是天接受了他；让他主持政事而政事办得好、百姓安乐，就是百姓接受了他。天给他，人也给他，所以说：天子不能把天下给别人。"},{id:"jie5_s3",label:"天视自我民视，天听自我民听",showLabel:!0,sentences:[["舜相尧，二十有八载，非人之所能为也，天也。尧崩，三年之丧毕，舜避尧之子于南河之南。天下诸侯朝觐者，不之尧之子而之舜；讼狱者，不之尧之子而之舜；讴歌者，不讴歌尧之子而讴歌舜；故曰‘天’也。夫然后之中国，践天子位焉。而居尧之宫，逼尧之子，是‘篡’也，非‘天与’也。《泰誓》曰：‘天视自我民视，天听自我民听’，此之谓也。”"]],note:"孟子接着说：「舜辅佐尧二十八年，这不是人力所能做到的，是天意。尧去世，三年之丧完毕，舜避开尧的儿子，到南河的南边去。可天下诸侯朝见的，不到尧的儿子那里而去舜那里；打官司的，不到尧的儿子那里而去舜那里；歌颂的，不歌颂尧的儿子而歌颂舜——所以才说『是天意』。这样之后，舜才回到国都，登上天子之位。如果他住在尧的宫里、逼着尧的儿子，那就是『篡』，不是『天与』了。《泰誓》上说：『天所看的，来自百姓所看；天所听的，来自百姓所听』，说的就是这个。」"}],b=[],y=[{id:"jie6_s1",label:"天与贤则与贤，天与子则与子",showLabel:!0,sentences:[["万章问曰：“人有言‘至于禹而德衰，不传于贤而传于子’，有诸？”孟子曰：“否然也。天与贤则与贤，天与子则与子。昔者舜荐禹于天，十有七年；舜崩，三年之丧毕，禹避舜之子于阳城；天下之民从之，若尧崩之后不从尧之子而从舜也。禹荐益于天，七年，禹崩，三年之丧毕，益避禹子于箕山之阴；朝觐讼狱者，不之益而之启，曰：‘吾君之子也。’讴歌者不讴歌益而讴歌启，曰：‘吾君之子也。’丹朱之不肖，舜之子亦不肖；舜之相尧、禹之相舜也，历年多，施泽于民久。启贤，能敬承继禹之道；益之相禹也，历年少，施泽于民未久。舜、禹、益相去久远，其子之贤不肖皆天也，非人之所能为也。"]],note:"万章问：「有人说『到禹的时候德行就衰了，不传位给贤人而传给儿子』，有这回事吗？」孟子说：「不对。天要授给贤人就授给贤人，天要授给儿子就授给儿子。从前舜向天推荐禹，经过了十七年；舜去世，三年之丧完毕，禹避开舜的儿子，到阳城去；可天下的百姓都跟从他，就像尧去世之后百姓不跟从尧的儿子而跟从舜一样。禹向天推荐益，过了七年，禹去世，三年之丧完毕，益避开禹的儿子，到箕山北面去；可朝见、打官司的人不到益那里而去启那里，说：『这是我们君主的儿子。』歌颂的人不歌颂益而歌颂启，说：『这是我们君主的儿子。』丹朱不贤，舜的儿子也不贤；而舜辅佐尧、禹辅佐舜的年头多，给百姓的恩泽久。启贤能，能恭谨地继承禹的道；而益辅佐禹的年头少，给百姓的恩泽不久。舜、禹、益相距的时间有长有短，他们儿子的贤与不贤都是天意，不是人力所能决定的。"},{id:"jie6_s2",label:"莫之为而为者，天也；莫之致而至者，命也",showLabel:!0,sentences:[["莫之为而为者，天也；莫之致而至者，命也。匹夫而有天下者，德必若舜禹，而又有天子荐之者；故仲尼不有天下。继世而有天下，天之所废，必若桀纣者也；故益、伊尹、周公不有天下。伊尹相汤以王于天下，汤崩，太丁未立，外丙二年，仲壬四年。太甲颠覆汤之典刑，伊尹放之于桐三年；太甲悔过，自怨自艾，于桐处仁迁义，三年以听伊尹之训己也，复归于亳。周公之不有天下，犹益之于夏、伊尹之于殷也。孔子曰：‘唐虞禅，夏后、殷、周继，其义一也。’”"]],note:"孟子接着说：「没有什么人去做而自然做成的，是天；没有什么人去招致而自然到来的，是命。平民而能拥有天下，德行一定得像舜、禹，而且又有天子推荐他——所以孔子不曾拥有天下。继承世代而拥有天下，天所要废弃的，一定得像桀、纣那样——所以益、伊尹、周公都不曾拥有天下。伊尹辅佐汤而称王天下，汤去世后，太丁未立而亡，外丙在位两年，仲壬在位四年。太甲颠覆了汤的典章刑法，伊尹把他放逐到桐三年；太甲悔过，自怨自责，在桐地存仁行义，三年之中听从伊尹对自己的训导，然后回到亳都复位。周公不曾拥有天下，就如同益之于夏、伊尹之于殷一样。孔子说：『唐尧、虞舜是禅让，夏后、殷、周是继承，其中的道理是一样的。』」"}],j=[],x=[{id:"jie7_s1",label:"伊尹耕于有莘之野",showLabel:!0,sentences:[["万章问曰：“人有言‘伊尹以割烹要汤’，有诸？”孟子曰：“否，不然。伊尹耕于有莘之野，而乐尧舜之道焉。非其义也，非其道也，禄之以天下弗顾也，系马千",{text:"驷",glossary:"si-2"},"弗视也。非其义也，非其道也，一介不以与人，一介不以取诸人。汤使人以币聘之。",{text:"嚣嚣然",glossary:"xiaoxiao-2"},"曰：‘我何以汤之聘币为哉？我岂若处畎亩之中，由是以乐尧舜之道哉？’汤三使往聘之。"]],note:"万章问：「有人说『伊尹靠烹调之技去求见商汤』，有这回事吗？」孟子说：「不对，不是这样。伊尹在有莘的田野里耕种，以尧舜之道为乐。不合于义、不合于道，即使拿天下来做他的俸禄，他也不看一眼；即使有四千匹马系在那里，他也不看一眼。不合于义、不合于道，一点小东西也不给别人，一点小东西也不向别人取。汤派人带着礼物去聘请他，他满不在乎地说：『我要汤的聘礼做什么呢？我何不如待在田野里，由此以尧舜之道为乐呢？』汤三次派人去聘请他。"},{id:"jie7_s2",label:"予将以斯道觉斯民也",showLabel:!0,sentences:[["既而幡然改曰：‘与我处畎亩之中，由是以乐尧舜之道，吾岂若使是君为尧舜之君哉？吾岂若使是民为尧舜之民哉？吾岂若于吾身亲见之哉？天之生此民也，使先知觉后知，使先觉觉后觉也。予，天民之先觉者也。予将以斯道觉斯民也，非予觉之而谁也？’思天下之民匹夫匹妇有不被尧舜之泽者，若己推而内之沟中。其自任以天下之重如此，故就汤而说之以伐夏救民。"]],note:"孟子接着说：「不久他就改变主意说：『与其我待在田野里、由此以尧舜之道为乐，何不如使这位君主成为尧舜那样的君主呢？何不如使这些百姓成为尧舜时的百姓呢？何不如让我亲眼看到呢？上天生育这些百姓，是要让先明白的人去启发后明白的人，让先觉悟的人去启发后觉悟的人。我，就是上天之民中先觉悟的人。我将用这个道去启发这些百姓——不是我启发他们，又是谁呢？』他想到天下百姓中有一个男丁一个妇女没受到尧舜的恩泽，就像自己把他们推进山沟里一样。他这样把天下的重担担在自己肩上，所以去接近汤，劝他讨伐夏桀、拯救百姓。"},{id:"jie7_s3",label:"吾闻其以尧舜之道要汤，未闻以割烹也",showLabel:!0,sentences:[["吾未闻枉己而正人者也，况辱己以正天下者乎？圣人之行不同也，或远或近，或去或不去，归洁其身而已矣。吾闻其以尧舜之道要汤，未闻以割烹也。《伊训》曰：‘天诛造攻自牧宫，朕载自亳。’”"]],note:"孟子接着说：「我没听说过自己不正却能正别人的，何况侮辱自己来正天下呢？圣人的行为各不相同，有的远、有的近，有的离去、有的不离，归根结底是使自己保持高洁罢了。我听说的是他用尧舜之道去求汤，没听说过用烹调。《伊训》上说：『上天诛伐的祸端从牧宫开始，（商汤）我从亳都起事。』」"}],f=[{id:"si-2",term:"驷",pinyin:"sì",meaning:"四匹马为一驷。「系马千驷」谓有四千匹马，极言其富。"},{id:"xiaoxiao-2",term:"嚣嚣然",pinyin:"xiāo xiāo rán",meaning:"自得、满不在乎的样子。"}],w=[{id:"jie8_s1",label:"孔子于卫主痈疽",showLabel:!0,sentences:[["万章问曰：“或谓‘孔子于卫主",{text:"痈疽",glossary:"yongju"},"，于齐主侍人",{text:"瘠环",glossary:"jihuan"},"’，有诸乎？”孟子曰：“否，不然也，好事者为之也。于卫，主",{text:"颜雠由",glossary:"yanchouyou"},"。弥子之妻与子路之妻，兄弟也。弥子谓子路曰：‘孔子主我，卫卿可得也。’子路以告，孔子曰：‘有命。’孔子进以礼，退以义，得之不得曰：‘有命’。而主痈疽与侍人瘠环，是无义无命也。"]],note:"万章问：「有人说『孔子在卫国住在痈疽家里，在齐国住在宦官瘠环家里』，有这回事吗？」孟子说：「不对，不是这样，是好事的编造的。孔子在卫国，住在颜雠由家里。弥子瑕的妻子和子路的妻子是姊妹。弥子瑕对子路说：『如果孔子肯住在我家，卫国的卿位就可以得到。』子路把这告诉孔子，孔子说：『这取决于命运。』孔子以礼而进，以义而退，得到得不到都说『取决于命运』。如果他去住在痈疽和宦官瘠环家里，那就是不讲义也不讲命了。"},{id:"jie8_s2",label:"观近臣，以其所为主",showLabel:!0,sentences:[["孔子不悦于鲁卫，遭宋桓司马，将要而杀之，微服而过宋。是时孔子当厄，主司城贞子，为陈侯周臣。吾闻观近臣，以其所为主；观远臣，以其所主。若孔子主痈疽与侍人瘠环，何以为孔子？”"]],note:"孟子接着说：「孔子在鲁国、卫国都不顺心，又遇上宋国的桓司马要在路上截杀他，他就换上便装通过宋国。那时孔子处境窘困，住在司城贞子家里，做了陈侯周的臣子。我听说：看朝廷的近臣，要看他所招待的是什么人；看外来的远臣，要看他所寄住的是什么人。如果孔子住在痈疽和宦官瘠环家里，那还怎么算孔子呢？」"}],z=[{id:"yongju",term:"痈疽",pinyin:"yōng jū",meaning:"此处为人名，据传是卫国一个靠治痈疽（毒疮）得宠的人，与下文「侍人瘠环」同为小人。"},{id:"jihuan",term:"瘠环",pinyin:"jí huán",meaning:"齐国的宦官（侍人即宦官）。"},{id:"yanchouyou",term:"颜雠由",pinyin:"yán chóu yóu",meaning:"卫国的贤大夫，孔子在卫国时曾住在他家。"}],k=[{id:"jie9_s1",label:"百里奚自鬻于秦养牲者",showLabel:!0,sentences:[["万章问曰：“或曰：‘百里奚自鬻于秦养牲者，五羊之皮。食牛，以要秦缪公。’信乎？”孟子曰：“否然，好事者为之也。百里奚，虞人也。晋人以垂棘之璧与屈产之乘，假道于虞以伐虢。",{text:"宫之奇",glossary:"gongzhiqi"},"谏，百里奚不谏，知虞公之不可谏而去。之秦，年已七十矣，曾不知以食牛干秦缪公之为污也，可謂智乎？"]],note:"万章问：「有人说：『百里奚把自己卖给秦国养牲畜的人，换五张羊皮，替人喂牛，以此求见秦缪公。』可信吗？」孟子说：「不对，是好事的编造的。百里奚是虞国人。晋国人用垂棘的玉璧和屈地出产的马，向虞国借路去攻打虢国。宫之奇劝谏，百里奚不劝谏——他知道虞公不可劝谏，就离开了。他到秦国时，年纪已经七十了，竟会不知道用替人喂牛的方式去求见秦缪公是污浊的吗——那还能算聪明吗？"},{id:"jie9_s2",label:"自鬻以成其君，乡党自好者不为",showLabel:!0,sentences:[["不可谏而不谏，可谓不智乎？知虞公之将亡而先去之，不可谓不智也。时举于秦，知缪公之可与有行也而相之，可谓不智乎？相秦而显其君于天下，可传于后世，不贤而能之乎？自鬻以成其君，乡党自好者不为，而谓贤者为之乎？”"]],note:"孟子接着说：「知道不可劝谏就不去劝谏，能说他不聪明吗？知道虞公将要亡国而先离开，不能说他不聪明。他在秦国被举用，知道缪公可以一同有所作为就去辅佐他，能说他不聪明吗？辅佐秦国而使他的君主显名于天下，可以流传后世——不是贤人能做到吗？靠卖身来成就自己的君主，乡里中自爱的人都不肯做，难道说贤人会做吗？」"}],T=[{id:"gongzhiqi",term:"宫之奇",pinyin:"gōng zhī qí",meaning:"虞国大夫，曾劝谏虞公不要借路给晋国（「唇亡齿寒」之谏），虞公不听，虞国终为晋所灭。"}];return(G,n)=>{const o=L("DaoTextReading");return P(),c("div",null,[n[0]||(n[0]=r('<h1 id="孟子·万章上" tabindex="-1">孟子·万章上 <a class="header-anchor" href="#孟子·万章上" aria-label="Permalink to &quot;孟子·万章上&quot;">​</a></h1><h2 id="【原典层】原文" tabindex="-1">【原典层】原文 <a class="header-anchor" href="#【原典层】原文" aria-label="Permalink to &quot;【原典层】原文&quot;">​</a></h2><p>《万章上》九章，<strong>章数最少而篇幅最长</strong>。九章多为万章、咸丘蒙的问难，内容集中在三件事：<strong>舜的孝与其家庭的凶险</strong>（一至三）、<strong>尧舜禹之间的传授究竟是「与」还是「天与」</strong>（四至六）、<strong>伊尹、孔子、百里奚的传闻之辨</strong>（七至九）。</p><p>读法：<strong>默认竹简模式</strong>，适合沉浸通读；切到右上角<strong>经典阅读</strong>，原文中的生词可点击查看释义。每节之下另附<strong>字词卡片</strong>。</p><hr><h3 id="一、大孝终身慕父母" tabindex="-1">一、大孝终身慕父母 <a class="header-anchor" href="#一、大孝终身慕父母" aria-label="Permalink to &quot;一、大孝终身慕父母&quot;">​</a></h3><p>万章问舜为何「号泣于旻天」，孟子答「<strong>怨慕</strong>」——怨自己不得父母欢心，又思慕父母。中段引公明高，说孝子之心「不若是恝」。末段是全章重心：<strong>士人悦之、二女、富有天下、贵为天子，皆「不足以解忧」，惟顺于父母可以解忧</strong>；收在**「大孝终身慕父母，五十而慕者，予于大舜见之矣」**。</p>',7)),i(o,{sections:e,glossary:l,"default-mode":"slips","aria-label":"孟子·万章上·第一节 原文"}),n[1]||(n[1]=s("hr",null,null,-1)),n[2]||(n[2]=s("h3",{id:"二、舜之不告而娶",tabindex:"-1"},[t("二、舜之不告而娶 "),s("a",{class:"header-anchor",href:"#二、舜之不告而娶","aria-label":'Permalink to "二、舜之不告而娶"'},"​")],-1)),n[3]||(n[3]=s("p",null,[t("三问三答。第一问答「不告而娶」："),s("strong",null,"「告则不得娶……如告则废人之大伦以懟父母，是以不告也。」"),t(" 第二段是舜家庭最惨的一节——"),s("strong",null,"完廩焚廩、浚井掩井、象分财物"),t("。末段最关键：象以「爱兄之道来」，舜便诚信而喜之；孟子引子产与校人（生鱼被烹而子产说「得其所哉」）作比，给出那句判语："),s("strong",null,"「故君子可欺以其方，难罔以非其道。」")],-1)),i(o,{sections:a,glossary:g,"default-mode":"slips","aria-label":"孟子·万章上·第二节 原文"}),n[4]||(n[4]=s("hr",null,null,-1)),n[5]||(n[5]=s("h3",{id:"三、象日以杀舜为事",tabindex:"-1"},[t("三、象日以杀舜为事 "),s("a",{class:"header-anchor",href:"#三、象日以杀舜为事","aria-label":'Permalink to "三、象日以杀舜为事"'},"​")],-1)),n[6]||(n[6]=s("p",null,[t("万章质疑：四罪皆诛，为何独对象只「封」？孟子答："),s("strong",null,"「仁人之于弟也，不藏怒焉，不宿怨焉，亲爱之而已矣。」"),t(" 并解释「或曰放」——象不得有为于其国，天子派吏治之、只纳贡税，故谓之放；而「欲常常而见之，故源源而来」。")],-1)),i(o,{sections:u,glossary:d,"default-mode":"slips","aria-label":"孟子·万章上·第三节 原文"}),n[7]||(n[7]=s("hr",null,null,-1)),n[8]||(n[8]=s("h3",{id:"四、此非君子之言-齐东野人之语也",tabindex:"-1"},[t("四、此非君子之言，齐东野人之语也 "),s("a",{class:"header-anchor",href:"#四、此非君子之言-齐东野人之语也","aria-label":'Permalink to "四、此非君子之言，齐东野人之语也"'},"​")],-1)),n[9]||(n[9]=s("p",null,[t("咸丘蒙引「盛德之士，君不得而臣，父不得而子」。孟子斥为**「齐东野人之语」"),s("strong",null,"，并用《尧典》「二十有八载，放勋乃徂落」与孔子「天无二日，民无二王」驳之。中段是全书极重要的"),t("说《诗》之法**："),s("strong",null,"「不以文害辞，不以辞害志；以意逆志，是为得之。」"),t(" 末段论「孝子之至，莫大乎尊亲；尊亲之至，莫大乎以天下养」。")],-1)),i(o,{sections:h,glossary:m,"default-mode":"slips","aria-label":"孟子·万章上·第四节 原文"}),n[10]||(n[10]=s("hr",null,null,-1)),n[11]||(n[11]=s("h3",{id:"五、天子不能以天下与人",tabindex:"-1"},[t("五、天子不能以天下与人 "),s("a",{class:"header-anchor",href:"#五、天子不能以天下与人","aria-label":'Permalink to "五、天子不能以天下与人"'},"​")],-1)),n[12]||(n[12]=s("p",null,[t("万章问「尧以天下与舜，有诸」，孟子斩然答："),s("strong",null,"「否，天子不能以天下与人。」"),t(" 那么谁给的？"),s("strong",null,"「天与之。」"),t(" 天如何示之？——"),s("strong",null,"「天不言，以行与事示之而已矣。」"),t(" 具体是「使之主祭而百神享之，是天受之；使之主事而事治，百姓安之，是民受之也」。末引《泰誓》"),s("strong",null,"「天视自我民视，天听自我民听」"),t("——天意即民意。")],-1)),i(o,{sections:p,glossary:b,"default-mode":"slips","aria-label":"孟子·万章上·第五节 原文"}),n[13]||(n[13]=s("hr",null,null,-1)),n[14]||(n[14]=s("h3",{id:"六、天与贤则与贤-天与子则与子",tabindex:"-1"},[t("六、天与贤则与贤，天与子则与子 "),s("a",{class:"header-anchor",href:"#六、天与贤则与贤-天与子则与子","aria-label":'Permalink to "六、天与贤则与贤，天与子则与子"'},"​")],-1)),n[15]||(n[15]=s("p",null,[t("驳「至于禹而德衰」之说："),s("strong",null,"「天与贤则与贤，天与子则与子。」"),t(" 以舜荐禹、禹荐益为例，说明"),s("strong",null,"民从谁、讴歌谁，就是天意所在"),t("；而「舜、禹、益相去久远，其子之贤不肖皆天也」。末段给出两句极重的话："),s("strong",null,"「莫之为而为者，天也；莫之致而至者，命也。」"),t(" 并历数孔子、益、伊尹、周公之不有天下。")],-1)),i(o,{sections:y,glossary:j,"default-mode":"slips","aria-label":"孟子·万章上·第六节 原文"}),n[16]||(n[16]=s("hr",null,null,-1)),n[17]||(n[17]=s("h3",{id:"七、伊尹以割烹要汤",tabindex:"-1"},[t("七、伊尹以割烹要汤 "),s("a",{class:"header-anchor",href:"#七、伊尹以割烹要汤","aria-label":'Permalink to "七、伊尹以割烹要汤"'},"​")],-1)),n[18]||(n[18]=s("p",null,[t("驳「伊尹以割烹要汤」。先写伊尹之守：「非其义也，非其道也，禄之以天下弗顾也，系马千驷弗视也。」再写汤三聘而伊尹幡然改志——"),s("strong",null,"「予，天民之先觉者也。予将以斯道觉斯民也，非予觉之而谁也？」"),t(" 他的自任是「思天下之民匹夫匹妇有不被尧舜之泽者，若己推而内之沟中」。落句："),s("strong",null,"「吾未闻枉己而正人者也，况辱己以正天下者乎？」")],-1)),i(o,{sections:x,glossary:f,"default-mode":"slips","aria-label":"孟子·万章上·第七节 原文"}),n[19]||(n[19]=s("hr",null,null,-1)),n[20]||(n[20]=s("h3",{id:"八、孔子于卫主痈疽",tabindex:"-1"},[t("八、孔子于卫主痈疽 "),s("a",{class:"header-anchor",href:"#八、孔子于卫主痈疽","aria-label":'Permalink to "八、孔子于卫主痈疽"'},"​")],-1)),n[21]||(n[21]=s("p",null,[t("驳「孔子于卫主痈疽，于齐主侍人瘠环」。孟子的判语是**「好事者为之也」"),s("strong",null,"，并指出孔子「进以礼，退以义，得之不得曰有命」，不会去住小人家里。末句给出一个识人法："),t("「观近臣，以其所为主；观远臣，以其所主。」**")],-1)),i(o,{sections:w,glossary:z,"default-mode":"slips","aria-label":"孟子·万章上·第八节 原文"}),n[22]||(n[22]=s("hr",null,null,-1)),n[23]||(n[23]=s("h3",{id:"九、百里奚自鬻于秦",tabindex:"-1"},[t("九、百里奚自鬻于秦 "),s("a",{class:"header-anchor",href:"#九、百里奚自鬻于秦","aria-label":'Permalink to "九、百里奚自鬻于秦"'},"​")],-1)),n[24]||(n[24]=s("p",null,[t("驳「百里奚自鬻于秦养牲者，五羊之皮」。孟子以「智」字层层反问：知虞公之不可谏而不谏、知虞公将亡而先去、知缪公可与有行而相之，皆不可谓不智。末句最有力："),s("strong",null,"「自鬻以成其君，乡党自好者不为，而谓贤者为之乎？」")],-1)),i(o,{sections:k,glossary:T,"default-mode":"slips","aria-label":"孟子·万章上·第九节 原文"}),n[25]||(n[25]=r('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一篇在说什么" tabindex="-1">象：这一篇在说什么 <a class="header-anchor" href="#象-这一篇在说什么" aria-label="Permalink to &quot;象：这一篇在说什么&quot;">​</a></h3><p>《万章上》九章，<strong>章数最少而篇幅最长</strong>——它不像前几篇那样排出一串格言，而是<strong>九场针锋相对的问答</strong>。可分三束：</p><p><strong>一束是舜</strong>（一至三）。舜为什么对着天哭号？因为「怨慕」。舜为什么不告而娶？因为「告则不得娶」。舜为什么把天天想杀他的象封在有庳？因为**「仁人之于弟也，不藏怒焉，不宿怨焉」<strong>。这三章合起来，是《孟子》里对</strong>舜的家**写得最细的地方——<strong>父亲要烧死他，弟弟要杀他，而他五十岁还在思慕父母。</strong></p><p><strong>二束是天与</strong>（四至六）。尧到底把天下给了舜没有？给舜的是天？还是人民？孟子给了三层递推：<strong>「天子不能以天下与人」→「天与之」→「天视自我民视，天听自我民听」</strong>。而禹传子不传贤，也同样是天——<strong>「天与贤则与贤，天与子则与子。」</strong></p><p><strong>三束是辨诬</strong>（七至九）。伊尹「以割烹要汤」？孔子「主痈疽、瘠环」？百里奚「自鬻于秦」？孟子的判语几乎完全一样：<strong>「否，不然，好事者为之也。」</strong> 他反复用的是同一个逻辑：<strong>真正的人，不会用那种手段；用那种手段的，就不是那样的人。</strong></p><h3 id="理-为什么值得读" tabindex="-1">理：为什么值得读 <a class="header-anchor" href="#理-为什么值得读" aria-label="Permalink to &quot;理：为什么值得读&quot;">​</a></h3><ul><li><strong>「怨慕」二字是理解舜的关键</strong>：不是怨父母，是<strong>怨自己</strong>不得父母欢心，同时<strong>又思慕</strong>父母。这两种心情并存在一起，才有了「号泣于旻天」。</li><li><strong>第一章的排比极见分量</strong>：天下士人悦之、娶尧之二女、富有天下、贵为天子——<strong>四样人人所求的东西，都「不足以解忧」</strong>。只有一件事能解忧：<strong>顺于父母</strong>。而接下来那句「人少则慕父母，知好色则慕少艾，有妻子则慕妻子，仕则慕君，不得于君则热中」，把<strong>人一生的心思迁移描得清清楚楚</strong>；衬托出「大孝终身慕父母」的分量。</li><li><strong>「不告而娶」不是不孝，是「两害相权」</strong>：告了就娶不成，娶不成则废人伦、又使父母担怨。孟子的辩解其实是**「礼」与「更大的礼」相冲突时的取舍**。</li><li><strong>「完廩焚廩」「浚井掩井」之后，舜那句「唯兹臣庶，汝其于予治」，是《孟子》里最复杂的一笔</strong>。而孟子紧接着用子产与校人的故事作解：<strong>「君子可欺以其方，难罔以非其道。」</strong> —— 舜不是愚蠢，是<strong>用爱兄之道去看待弟弟</strong>；那不是被蒙蔽，那是他的为人方式。</li><li><strong>「仁人之于弟也，不藏怒焉，不宿怨焉」是孟子的「亲爱」观</strong>：亲爱不是不生气，而是<strong>不把怒和怨存起来</strong>。</li><li><strong>第四章是全书极重要的「说《诗》之法」</strong>：<strong>「不以文害辞，不以辞害志；以意逆志，是为得之。」</strong> 举的例子是《云汉》「周余黎民，靡有孑遗」——若照字面信，周朝就没有活人了。<strong>这是中国文学批评史上最早、最清楚的一条解释原则。</strong></li><li><strong>「孝子之至，莫大乎尊亲；尊亲之至，莫大乎以天下养」把「孝」推到了它的最高形态</strong>：拿天下来奉养父母——不是排场，而是**「尊」与「养」都到了极限**。</li><li><strong>「天子不能以天下与人」是一个极硬的政治判断</strong>：天下不是任何人的私产，<strong>连天子也没有权转让</strong>。而「天与之」的实际内容是<strong>民受之</strong>——「使之主事而事治，百姓安之，是民受之也」。</li><li><strong>「天视自我民视，天听自我民听」是这一卷最重的一句话</strong>：天不是另一个说话的人，<strong>天意就是民意</strong>。这是孟子把「天命」还原为「民心」的关键一步。</li><li><strong>「莫之为而为者，天也；莫之致而至者，命也」是《孟子》对「天」与「命」下得最干净的定义</strong>：没有人去做却做成了，是天；没有人去招却来了，是命。</li><li><strong>第六章还给「禅让」与「继承」下了同一个判断</strong>：孔子说「唐虞禅，夏后、殷、周继，<strong>其义一也</strong>」——形式不同，道理是一个。</li><li><strong>第七章是全书的「先觉」宣言</strong>：<strong>「天之生此民也，使先先知觉后知，使先觉觉后觉也。予，天民之先觉者也。」</strong> 而伊尹的自任是**「思天下之民匹夫匹妇有不被尧舜之泽者，若己推而内之沟中」** ——<strong>把别人的困境当成自己把人推进沟里。</strong></li><li><strong>第七章的两句话可以当座右铭</strong>：<strong>「吾未闻枉己而正人者也，况辱己以正天下者乎？」</strong> 以及「圣人之行不同也，或远或近，或去或不去，<strong>归洁其身而已矣</strong>」——<strong>圣人的做法各不相同，共同点是把自己弄干净。</strong></li><li><strong>第八章给出了一个极实用的识人法</strong>：<strong>「观近臣，以其所为主；观远臣，以其所主。」</strong> ——<strong>看他招待谁、看他住在谁家。</strong></li><li><strong>第九章的收尾最有力</strong>：<strong>「自鬻以成其君，乡党自好者不为，而谓贤者为之乎？」</strong> —— 用常识判断传闻：<strong>连乡里自爱的人都做不出的事，怎么会是贤者做的？</strong></li></ul><h3 id="用-今日可用之处" tabindex="-1">用：今日可用之处 <a class="header-anchor" href="#用-今日可用之处" aria-label="Permalink to &quot;用：今日可用之处&quot;">​</a></h3><ol><li><strong>用「怨慕」体会一次对父母的复杂心情</strong>：我对父母最难受的时候，心里怨的是他们，还是自己？</li><li><strong>用「不足以解忧」检查一次「拥有」与「安心」的区别</strong>：我这一年拼命想要的东西，得到了，真的解忧了吗？</li><li><strong>用「终身慕父母，五十而慕」问一次自己</strong>：我上一次想到父母，是什么时候？</li><li><strong>用「告则不得娶」看一次「两难中的取舍」</strong>：当两条规矩相冲突，我选的是哪一条？理由说得出口吗？</li><li><strong>用「君子可欺以其方，难罔以非其道」想一次被骗的经历</strong>：我那次是不是被一个**「合情合理」的说辞**骗了？——<strong>这不是蠢，是我还按自己的方式看人。</strong></li><li><strong>用「不藏怒焉，不宿怨焉」检查一次和亲近的人的关系</strong>：我有没有把某次生气「存起来」？</li><li><strong>用「不以文害辞，不以辞害志」检查一次阅读（也检查一次听人说话）</strong>：我是在抠字眼，还是在求他的本意？</li><li><strong>用「以意逆志」练一次理解</strong>：把对方的处境想一遍，再判断他那句话。</li><li><strong>用「天子不能以天下与人」想一次「权」的边界</strong>：我手上这一点权力，有哪些是<strong>不能用来转让</strong>的？</li><li><strong>用「天视自我民视，天听自我民听」校准一次判断</strong>：我说「大家都这样认为」的时候，是真的问过了大家，还是我听了几个人？</li><li><strong>用「莫之为而为者，天也；莫之致而至者，命也」安放一次得失</strong>：这件事成了（或败了），有没有我使不上力的那一部分？</li><li><strong>用「予，天民之先觉者也」问一次自己的责任</strong>：我在某件事上比别人先明白——那我做了什么？</li><li><strong>用「思天下之民匹夫匹妇有不被尧舜之泽者，若己推而内之沟中」掂量一次「担当」的重量</strong>：我关心别人，关心到什么程度？</li><li><strong>用「归洁其身而已矣」简化一次是非</strong>：圣人做法各不相同，共同点是<strong>把自己弄干净</strong>——那我呢？</li><li><strong>用「观其所为主」「观其所主」看一个人（也看自己）</strong>：他招待谁、住在谁家；我最近亲近的，是什么人？</li><li><strong>用「乡党自好者不为，而谓贤者为之乎」抵挡一次传闻</strong>：这条八卦，连普通人都不屑做——那么可信吗？</li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>《万章上》九章，是《孟子》里最长也最有意思的一卷。它不是格言集，而是<strong>九场问答</strong>——万章、咸丘蒙不停发问，孟子一题一题地答。</p><p>开头三章讲舜，也讲舜那个可怕的家。</p><p>万章先问：舜到田里种地，对着天哭号，为什么？孟子答了两个字：<strong>「怨慕。」</strong> ——怨自己不得父母欢心，又思慕父母。万章不懂：父母爱他就高兴、父母嫌他就多干活不抱怨，怎么还会「怨」？孟子于是讲了一段很动人的话：尧派了九个儿子、两个女儿，加上百官、牛羊、仓廩去侍奉舜，天下的士人都来归附他，尧还要把天下都让给他——<strong>可舜因为不得父母的欢心，像穷人一样无处可归。</strong> 天下人的喜爱、美貌、财富、尊贵，<strong>一样一样都不足以解忧</strong>；只有顺了父母的心，才能解忧。最后是那句：「<strong>大孝终身慕父母，五十而慕者，予于大舜见之矣。</strong>」</p><p>接着万章又问：既然《诗》上说娶妻一定要禀告父母，舜为什么不告就娶？孟子说：<strong>告了就娶不成；娶不成，就废了人伦，还让父母担怨——所以不告。</strong></p><p>再往下是舜家里最凶的一段。父母让他去修粮仓，抽掉梯子，瞽瞍放火；让他去淘井，等他下去就填土。弟弟象说：「谋害舜都是我的功劳。牛羊归父母，仓廩归父母，干戈归我，琴归我，弓归我，两位嫂子让她们替我管家。」然后象走进舜的宫室，舜正在弹琴。象说：「我正闷闷地想念你哪。」脸上却很难看。舜说：「这些臣民，你就替我管理吧。」——万章于是问：舜难道不知道象要杀他吗？孟子说：怎么不知道，只是<strong>象忧愁他也忧愁，象欢喜他也欢喜</strong>。万章追问：那舜是假装高兴？孟子就讲了子产和一条鱼的故事：有人送子产活鱼，管池子的人把鱼煮着吃了，回来报告说「刚放下时还蔫蔫的，一会儿就活络起来，一甩尾巴不见了」，子产说「找到好去处了！找到好去处了！」那人出来笑话子产傻。孟子的结论是：<strong>「故君子可欺以其方，难罔以非其道。」</strong> ——象是用「爱兄长」的说辞来的，所以舜真诚地相信并高兴了。<strong>哪里是假装呢？</strong></p><p>第三章仍在讲象：舜做了天子，为什么不罚他？孟子说：「是封他。」于是万章问：那四个人（共工、驩兜、三苗、鲧）都罚了，象最不仁却封，这算什么？孟子说：<strong>「仁人之于弟也，不藏怒焉，不宿怨焉，亲爱之而已矣。」</strong> 至于「有人说那是放逐」，是因为<strong>象不能在他的封国里做事</strong>，天子派官吏去治理、只收贡税——<strong>但这个安排里，还留着舜想常常见到弟弟的那份心。</strong></p><p>第四章转到另一个问题。咸丘蒙问：古语说「盛德之士，君不得而臣，父不得而子」，据说舜面南而坐，尧和瞽瞍都面北朝见他？孟子斥道：<strong>「此非君子之言，齐东野人之语也。」</strong> 他连引《尧典》「二十有八载，放勋乃徂落」和孔子「天无二日，民无二王」来驳。中间那一段最要紧，是孟子的<strong>读《诗》之法</strong>：<strong>「不以文害辞，不以辞害志；以意逆志，是为得之。」</strong> 他说，《云汉》里那句「周余黎民，靡有孑遗」，若照字面信，周朝就没有剩下的人了。最后一层也很重：<strong>「孝子之至，莫大乎尊亲；尊亲之至，莫大乎以天下养。」</strong></p><p>第五章是全卷最著名的一章。万章问：尧把天下给了舜，有这回事吗？孟子说：<strong>「天子不能以天下与人。」</strong> 那是谁给的？答：<strong>「天与之。」</strong> 天怎么说？答：<strong>「天不言，以行与事示之而已矣。」</strong> 怎么示？孟子说：让他主持祭祀而百神享用，是天接受；让他主持政事而百姓安乐，是人民接受。<strong>「天与之，人与之」</strong>——所以天子不能把天下送人。他还讲了一个细节：舜辅佐尧二十八年，尧死后，舜躲到南河的南边去；可诸侯朝见都去舜那里，打官司都去舜那里，唱歌都唱舜——<strong>这才是「天」。如果他住进尧的宫里、逼着尧的儿子，那就是「篡」。</strong> 最后引《泰誓》：<strong>「天视自我民视，天听自我民听。」</strong></p><p>第六章接着问：有人说禹的德行衰了，传位给儿子不传给贤人？孟子说：<strong>「天与贤则与贤，天与子则与子。」</strong> 舜推禹、禹推益，可禹死后百姓都跑去跟禹的儿子启——<strong>「吾君之子也」</strong>。为什么？因为启贤能，而益辅佐禹的年头短、施恩不久。他由此给出两句极干净的话：<strong>「莫之为而为者，天也；莫之致而至者，命也。」</strong> 又说孔子不曾有天下、益与伊尹与周公也不曾有天下，最后引孔子的话：<strong>「唐虞禅，夏后、殷、周继，其义一也。」</strong></p><p>最后三章，孟子一连驳了三条传闻。</p><p>有人说伊尹是靠烹调之技求见商汤的。孟子说不是。他先写伊尹的守：「非其义也，非其道也，禄之以天下弗顾也，系马千驷弗视也。」汤三次派人去请，伊尹本来满不在乎，后来却变了主意：<strong>「予，天民之先觉者也。予将以斯道觉斯民也，非予觉之而谁也？」</strong> 他想到天下有一个男人一个女人没受到尧舜的恩泽，就像自己把他们推进沟里。最后一句是：<strong>「吾未闻枉己而正人者也，况辱己以正天下者乎？」</strong></p><p>又有人说孔子在卫国住在痈疽家里、在齐国住在宦官瘠环家里。孟子说：<strong>「好事者为之也。」</strong> 他举出反证：孔子在卫国住在颜雠由家；弥子瑕想留他以便给他卿位，孔子只说「有命」——「孔子进以礼，退以义」，怎么会住到小人家里去？末了给出一个识人法：<strong>「观近臣，以其所为主；观远臣，以其所主。」</strong></p><p>最后一章问百里奚：有人说他把自己卖了五张羊皮，替人喂牛，以此求见秦缪公，真的吗？孟子又是一句「好事者为之也」，然后用「智」字一层层反问：他知道虞公不可谏就不谏，知道虞公将亡就先离开，知道缪公可辅佐就去辅佐，辅佐之后让君主显名天下——<strong>这哪一样不聪明？</strong> 收尾最有力：<strong>「自鬻以成其君，乡党自好者不为，而谓贤者为之乎？」</strong></p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p>待补——这一节留给自己的读后想法。</p></blockquote><p>可以按这几条慢慢写：</p><ul><li>「怨慕」——我对父母最难受的时候，怨的是他们，还是自己？</li><li>「不足以解忧」——我拼命想要的东西，得到了真的解忧了吗？</li><li>「五十而慕」——我上一次想到父母，是什么时候？</li><li>「君子可欺以其方，难罔以非其道」——我被骗的那次，是不是被一个「合情合理」的说辞骗了？</li><li>「不藏怒焉，不宿怨焉」——我有没有把某次生气「存起来」？</li><li>「不以文害辞，不以辞害志」——我是在抠字眼，还是在求他的本意？</li><li>「天子不能以天下与人」——我手上这一点权力，有哪些是不能用来转让的？</li><li>「天视自我民视」——我说「大家都这样认为」时，是真的问过大家吗？</li><li>「莫之为而为者，天也」——这件事的成败里，有没有我使不上力的那一部分？</li><li>「予，天民之先觉者也」——我在哪件事上比别人先明白？我做了什么？</li><li>「观其所为主」——我最近亲近的，是什么人？</li><li>「乡党自好者不为，而谓贤者为之乎」——我最近转述的那条传闻，经得起这句反问吗？</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/lizhimingde/sishu-wujing/mengzi/">孟子总览</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/">四书五经总览</a></li><li>同栏目：<a href="/Dao/lizhimingde/sishu-wujing/daxue/">大学</a> · <a href="/Dao/lizhimingde/sishu-wujing/zhongyong/">中庸</a> · <a href="/Dao/lizhimingde/sishu-wujing/lunyu/">论语</a></li><li>上篇：<a href="/Dao/lizhimingde/sishu-wujing/mengzi/chapter-08">孟子·离娄下</a></li><li>下篇：<a href="/Dao/lizhimingde/sishu-wujing/mengzi/chapter-10">孟子·万章下</a></li><li>参考：《孟子》朱熹《四书章句集注·孟子集注》；杨伯峻《孟子译注》</li></ul>',30))])}}});export{V as __pageData,C as default};
